import type { ResumeOptions } from "../../core/types.js";

/** Default key prefix for resume entries. */
export const DEFAULT_RESUME_KEY_PREFIX = "universal-player:";

/** Storage adapter used by resume helpers. */
export interface ResumeStore {
  read(key: string): number | null;
  write(key: string, time: number): void;
  clear(key: string): void;
}

/**
 * Creates a resume store.
 *
 * Storage failures (private mode, quota, disabled cookies) are swallowed and
 * surfaced as `null`/no-op results.
 */
export function createResumeStore(options: ResumeOptions = {}): ResumeStore {
  const storage = options.storage ?? (typeof localStorage === "undefined" ? null : localStorage);
  const prefix = options.key ?? DEFAULT_RESUME_KEY_PREFIX;

  const storageKey = (key: string): string => `${prefix}${key}`;

  return {
    read(key: string): number | null {
      if (storage === null) {
        return null;
      }

      try {
        const raw = storage.getItem(storageKey(key));

        if (raw === null) {
          return null;
        }

        const value = Number(raw);
        return Number.isFinite(value) && value > 0 ? value : null;
      } catch {
        return null;
      }
    },

    write(key: string, time: number): void {
      if (storage === null || !Number.isFinite(time) || time <= 0) {
        return;
      }

      try {
        storage.setItem(storageKey(key), String(time));
      } catch {
        // Best-effort by design.
      }
    },

    clear(key: string): void {
      if (storage === null) {
        return;
      }

      try {
        storage.removeItem(storageKey(key));
      } catch {
        // Best-effort by design.
      }
    },
  };
}
